const readline = require('readline');
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

function main() {
    const inp = new InputReader();
    inp.readln = () => rl.question('', (answer) => {
        rl.close();
        return answer;
    });
    // Note: The above approach won't work for multiple reads. Using a different approach.
    const lines = [];
    rl.on('line', (line) => {
        lines.push(line);
    });
    rl.on('close', () => {
        let idx = 0;
        const readln = () => lines[idx++];
        const readlnStrings = () => readln().split(' ');
        const readlnInts = () => readlnStrings().map(Number);
        const inp = {
            readln,
            readlnInt: () => parseInt(readln(), 10),
            readlnLong: () => BigInt(readln()),
            readlnDouble: () => parseFloat(readln()),
            readlnStrings,
            readlnInts,
            readlnLongs: () => readlnStrings().map(BigInt),
            readlnDoubles: () => readlnStrings().map(parseFloat)
        };
        solve(inp);
    });
}

main();

